<script setup lang="ts">
import { Settings2, Check, Download, FileUp, LoaderCircle, ShieldCheck, ArrowUpRight, Sparkles, Database } from 'lucide-vue-next'
const ctx=useQinbian(),settings=ref<any>(),checking=ref(false),connection=ref(''),backing=ref(false),restoring=ref(false),restoreOpen=ref(false),restoreFile=ref<File|null>(null),jobs=ref<any[]>([])
onMounted(async()=>{try{settings.value=await apiFetch('/api/settings');jobs.value=await apiFetch('/api/ai/jobs')}catch(e){ctx.error(e)}})
async function saveModel(){try{await apiFetch('/api/settings',{method:'PATCH',body:{model:settings.value.model}});ctx.notify('默认模型已保存')}catch(e){ctx.error(e)}}
async function check(){checking.value=true;connection.value='';try{const r=await apiFetch<any>('/api/settings/check-ai',{method:'POST'});connection.value=r.ok?'连接正常，可以开始制作组件。':'连接未完成'}catch(e:any){connection.value=e.data?.message||'暂时无法连接，请稍后重试'}finally{checking.value=false}}
async function backup(){backing.value=true;try{const blob=await apiFetch('/api/backups',{method:'POST',responseType:'blob'});downloadFile(blob,'秦编备份-'+new Date().toISOString().slice(0,10)+'.zip');ctx.notify('完整备份已下载')}catch(e){ctx.error(e)}finally{backing.value=false}}
async function restore(){if(!restoreFile.value)return;restoring.value=true;try{const body=new FormData();body.append('file',restoreFile.value);await apiFetch('/api/backups/restore',{method:'POST',body});await ctx.refreshThemes();restoreOpen.value=false;ctx.notify('备份已恢复，恢复前的数据也已自动备份');settings.value=await apiFetch('/api/settings')}catch(e){ctx.error(e)}finally{restoring.value=false}}
const status=(s:string)=>({queued:'准备中',running:'制作中',validating:'检查中',ready:'候选待确认',failed:'未完成',cancelled:'已取消',applied:'已采用'}[s]||s)
</script>
<template><div class="page settings-page"><header class="page-heading"><div><p class="eyebrow">照料书房 · 妥存心稿</p><h1>设置与备份<span class="title-dot">。</span></h1><p class="page-description">常用的偏好，以及值得留好的每一份稿件。</p></div></header><template v-if="settings"><section class="settings-section"><div class="settings-section-title"><Sparkles :size="20"/><div><h2>AI 制作</h2><p>模型负责推敲，规范守住章法，最后由你决定。</p></div></div><div class="settings-row"><div><h3>默认模型</h3><p>Pro用于精细制作，Flash适合较快地尝试灵感。</p></div><select v-model="settings.model" aria-label="默认AI模型" @change="saveModel"><option value="deepseek-v4-pro">DeepSeek V4 Pro</option><option value="deepseek-flash">DeepSeek Flash</option></select></div><div class="settings-row"><div><h3>连接状态</h3><p>{{settings.aiConfigured?'已从本机配置读取密钥，页面不会显示密钥内容。':'尚未读取到密钥，请检查记者团目录的env文件。'}}</p><span v-if="connection" class="connection-result">{{connection}}</span></div><button class="btn" :disabled="checking" @click="check"><LoaderCircle v-if="checking" :size="15" class="spin"/><ShieldCheck v-else :size="16"/>{{checking?'正在检查…':'检查连接'}}</button></div><details class="skill-details"><summary>查看精简制作规范</summary><pre>{{settings.skill}}</pre></details></section><section class="settings-section"><div class="settings-section-title"><Database :size="20"/><div><h2>本地数据</h2><p>文章、组件与图片，始终放在自己的电脑上。</p></div></div><div class="settings-row"><div><h3>完整备份</h3><p>包含SQLite数据库和图片原文件，不包含API密钥。</p></div><button class="btn" :disabled="backing" @click="backup"><Download :size="16"/>{{backing?'正在整理…':'下载完整备份'}}</button></div><div class="settings-row"><div><h3>从备份恢复</h3><p>恢复前会自动留存当前数据，便于再次找回。</p></div><button class="btn" @click="restoreOpen=true"><FileUp :size="16"/>选择备份恢复</button></div></section><section class="settings-section"><div class="settings-section-title"><Settings2 :size="20"/><div><h2>最近的 AI 制作</h2><p>保留制作结果与状态，方便回看尚未采用的候选。</p></div></div><div v-if="!jobs.length" class="quiet-note">还没有AI制作记录。</div><div v-for="job in jobs" :key="job.id" class="job-history"><div><strong>{{job.result?.name||job.request.prompt.slice(0,40)}}</strong><small>{{formatDate(job.createdAt)}} · {{job.model}} · {{status(job.status)}}</small><p v-if="job.error" class="error-message">{{job.error}}</p></div><details v-if="job.result"><summary>查看结果</summary><div class="history-candidate"><PaletteSwatches v-if="job.result.kind==='palette'" :palette="job.result.palette" compact/><HtmlPreview v-else :html="job.result.html" :max-height="400"/></div></details></div></section><footer class="page-footer"><span>秦编 1.0 · 一间安静的编排书房</span><small>单人本地使用</small></footer></template><UiModal v-if="restoreOpen" title="恢复秦编备份" subtitle="将使用备份中的文章、组件与图片。恢复前会自动备份当前数据。" @close="!restoring&&(restoreOpen=false)"><div class="form-stack"><label>选择备份文件<input type="file" accept=".zip,application/zip" @change="restoreFile=($event.target as HTMLInputElement).files?.[0]||null"></label><p class="small muted">请使用由秦编“下载完整备份”生成的ZIP文件。</p><div class="modal-actions"><button class="btn" :disabled="restoring" @click="restoreOpen=false">取消</button><button class="btn primary" :disabled="!restoreFile||restoring" @click="restore">{{restoring?'正在恢复…':'确认恢复备份'}}</button></div></div></UiModal></div></template>
